//! Checks of the Black–Litterman model against PyPortfolioOpt. The fixture is generated by
//! `scripts/reference/black_litterman.py`.

#![allow(clippy::unwrap_used)]

use finalytics_opt::*;
use finalytics_risk::Matrix;
use serde_json::{Value, json};

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/black_litterman.json")).unwrap()
}

fn floats(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect()
}

#[track_caller]
fn close_all(actual: &[f64], expected: &[f64], tolerance: f64, what: &str) {
    assert_eq!(actual.len(), expected.len(), "{what}: lengths differ");
    let scale = expected.iter().fold(0.0f64, |m, v| m.max(v.abs()));
    for (k, (a, e)) in actual.iter().zip(expected).enumerate() {
        assert!(
            (a - e).abs() <= tolerance * scale,
            "{what}[{k}]: {a} against the reference {e}"
        );
    }
}

fn covariance(f: &Value) -> Matrix {
    let labels: Vec<String> = serde_json::from_value(f["labels"].clone()).unwrap();
    Matrix::new(labels, floats(&f["covariance"])).unwrap()
}

fn model(f: &Value, case: &Value) -> BlackLitterman {
    BlackLitterman {
        covariance: covariance(f),
        prior: serde_json::from_value(case["prior"].clone()).unwrap(),
        views: serde_json::from_value(case["views"].clone()).unwrap(),
        tau: case["tau"].as_f64().unwrap(),
    }
}

#[test]
fn estimates_match_pyportfolioopt() {
    let f = fixture();
    for case in f["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let estimate = model(&f, case).estimate().unwrap();
        close_all(
            &estimate.prior_returns,
            &floats(&case["prior_returns"]),
            1e-14,
            &format!("{name}: prior"),
        );
        close_all(
            &estimate.posterior_returns,
            &floats(&case["posterior_returns"]),
            1e-13,
            &format!("{name}: posterior returns"),
        );
        close_all(
            estimate.posterior_covariance.values(),
            &floats(&case["posterior_covariance"]),
            1e-13,
            &format!("{name}: posterior covariance"),
        );
        close_all(
            &estimate.view_variances,
            &floats(&case["view_variances"]),
            1e-14,
            &format!("{name}: view variances"),
        );
    }
}

#[test]
fn a_certain_view_is_met_exactly() {
    let f = fixture();
    let case = &f["cases"][4];
    let estimate = model(&f, case).estimate().unwrap();
    assert!((estimate.posterior_returns[0] - 0.08).abs() < 1e-15);
}

#[test]
fn without_views_the_posterior_is_the_prior() {
    let f = fixture();
    let mut bl = model(&f, &f["cases"][0]);
    bl.views.clear();
    let estimate = bl.estimate().unwrap();
    assert_eq!(estimate.posterior_returns, estimate.prior_returns);
    let c = covariance(&f);
    for (a, b) in estimate
        .posterior_covariance
        .values()
        .iter()
        .zip(c.values())
    {
        assert!((a - 1.05 * b).abs() < 1e-17);
    }
    let solution = estimate
        .problem()
        .solve(&Objective::MeanVariance { risk_aversion: 2.5 })
        .unwrap();
    assert_eq!(solution.status, SolveStatus::Optimal);
}

#[test]
fn implied_risk_aversion_matches_pyportfolioopt() {
    let f = &fixture()["implied_risk_aversion"];
    let found = implied_risk_aversion(
        &floats(&f["returns"]),
        f["periods_per_year"].as_f64().unwrap(),
        f["risk_free_rate"].as_f64().unwrap(),
    )
    .unwrap();
    let expected = f["risk_aversion"].as_f64().unwrap();
    assert!(
        (found - expected).abs() < 1e-12 * expected,
        "{found} against {expected}"
    );
}

#[test]
fn inputs_are_validated() {
    let f = fixture();
    let mut bl = model(&f, &f["cases"][0]);
    bl.tau = 0.0;
    bl.views.push(
        serde_json::from_value(json!({
            "portfolio": {"nowhere": 1.0},
            "expected_return": 0.1,
            "uncertainty": {"method": "confidence", "confidence": 0.0}
        }))
        .unwrap(),
    );
    let Err(finalytics_core::Error::Validation(report)) = bl.estimate() else {
        panic!("expected a validation error");
    };
    let paths: Vec<&str> = report.issues().iter().map(|i| i.path.as_str()).collect();
    assert_eq!(
        paths,
        [
            "tau",
            "views[2].portfolio",
            "views[2].uncertainty.confidence"
        ]
    );

    // Two certain views on the same asset that disagree cannot both hold.
    let mut bl = model(&f, &f["cases"][4]);
    let certain = bl.views[0].clone();
    bl.views.push(View {
        expected_return: 0.02,
        ..certain
    });
    let error = bl.estimate().unwrap_err();
    assert!(error.to_string().contains("not independent"), "{error}");
}
